/**
 * Event Bus — In-memory publish/subscribe message broker.
 * Services publish events here; other services subscribe to react.
 * No service imports another service directly; all inter-service
 * communication flows through this bus.
 */

type Callback = (payload: unknown) => void;

export class EventBus {
  private subscribers: Map<string, Callback[]> = new Map();

  /**
   * Register a callback to be invoked whenever `event` is published.
   */
  subscribe(event: string, callback: Callback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }

  /**
   * Publish an event, synchronously invoking all registered subscribers.
   */
  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) ?? [];
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        // Prevent a bad subscriber from breaking the publisher
        console.error(`[EventBus] Error in subscriber for "${event}":`, err);
      }
    }
  }
}

/**
 * User Service — manages user CRUD operations.
 * Owns its own in-memory data store (Map<string, User>).
 * Publishes no events; subscribes to no events.
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(name: string, email: string): User {
    if (!name || !email) {
      throw new Error("name and email are required");
    }
    const user: User = { id: randomUUID(), name, email };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) throw new Error(`User not found: ${id}`);
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, fields: Partial<Pick<User, "name" | "email">>): User {
    const user = this.getById(id);
    if (fields.name !== undefined) user.name = fields.name;
    if (fields.email !== undefined) user.email = fields.email;
    this.store.set(id, user);
    return user;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`User not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Project Service — manages projects and membership.
 * Owns its own in-memory data store (Map<string, Project>).
 * Publishes no events; subscribes to no events.
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(name: string, description: string): Project {
    if (!name) throw new Error("name is required");
    const project: Project = {
      id: randomUUID(),
      name,
      description: description ?? "",
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) throw new Error(`Project not found: ${id}`);
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(
    id: string,
    fields: Partial<Pick<Project, "name" | "description">>
  ): Project {
    const project = this.getById(id);
    if (fields.name !== undefined) project.name = fields.name;
    if (fields.description !== undefined) project.description = fields.description;
    this.store.set(id, project);
    return project;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Project not found: ${id}`);
    this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.store.set(projectId, project);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    this.store.set(projectId, project);
    return project;
  }
}

/**
 * Task Service — manages tasks with status transitions.
 * Owns its own in-memory data store (Map<string, Task>).
 *
 * Status transitions are forward-only: todo → in-progress → done
 *
 * Events published:
 *   task.assigned       { taskId, taskTitle, assigneeId }
 *   task.statusChanged  { taskId, taskTitle, assigneeId, oldStatus, newStatus }
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

// Ordered list used to enforce forward-only transitions
const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

export class TaskService {
  private store: Map<string, Task> = new Map();

  constructor(private eventBus: EventBus) {}

  create(
    title: string,
    description: string,
    projectId: string
  ): Task {
    if (!title || !projectId) throw new Error("title and projectId are required");
    const task: Task = {
      id: randomUUID(),
      title,
      description: description ?? "",
      status: "todo",
      assigneeId: null,
      projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) throw new Error(`Task not found: ${id}`);
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  update(
    id: string,
    fields: Partial<Pick<Task, "title" | "description">>
  ): Task {
    const task = this.getById(id);
    if (fields.title !== undefined) task.title = fields.title;
    if (fields.description !== undefined) task.description = fields.description;
    this.store.set(id, task);
    return task;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Task not found: ${id}`);
    this.store.delete(id);
  }

  assign(taskId: string, assigneeId: string | null): Task {
    const task = this.getById(taskId);
    task.assigneeId = assigneeId;
    this.store.set(taskId, task);

    if (assigneeId !== null) {
      this.eventBus.publish("task.assigned", {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId,
      });
    }

    return task;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const oldIndex = STATUS_ORDER.indexOf(task.status);
    const newIndex = STATUS_ORDER.indexOf(newStatus);

    if (newIndex === -1) {
      throw new Error(`Invalid status: ${newStatus}`);
    }
    if (newIndex <= oldIndex) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". Only forward transitions are allowed (todo → in-progress → done).`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(taskId, task);

    this.eventBus.publish("task.statusChanged", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }
}

/**
 * Comment Service — manages comments on tasks.
 * Owns its own in-memory data store (Map<string, Comment>).
 *
 * Events published:
 *   comment.added  { commentId, taskId, taskTitle, authorId, authorName }
 *
 * The router passes taskTitle and authorName at call time so this service
 * never imports or calls other services directly (ADR-001 / ADR-002).
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();

  constructor(private eventBus: EventBus) {}

  /**
   * Create a comment.
   * `taskTitle` and `authorName` are provided by the caller (router) so
   * this service never needs to reach into another service's store.
   */
  create(
    taskId: string,
    authorId: string,
    body: string,
    taskTitle: string,
    authorName: string
  ): Comment {
    if (!taskId || !authorId || !body) {
      throw new Error("taskId, authorId, and body are required");
    }
    const comment: Comment = {
      id: randomUUID(),
      taskId,
      authorId,
      body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    this.eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId,
      taskTitle,
      authorId,
      authorName,
    });

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Notification Service — creates notifications from events.
 * Owns its own in-memory data store (Map<string, Notification>).
 *
 * Events subscribed:
 *   task.assigned      → creates notification for the assignee
 *   task.statusChanged → creates notification for the assignee (if any)
 *   comment.added      → creates notification for the task assignee (if any)
 *
 * Operations exposed: getByUser, markAsRead
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

// ---- Typed event payloads ----

interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: string;
  newStatus: string;
}

interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
  /** The task's current assignee — resolved by the router before publishing */
  assigneeId?: string | null;
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor(eventBus: EventBus) {
    // Subscribe to all relevant events
    eventBus.subscribe("task.assigned", (payload) => {
      const { taskId, taskTitle, assigneeId } =
        payload as TaskAssignedPayload;
      this.createNotification(
        assigneeId,
        `You have been assigned to task "${taskTitle}" (${taskId}).`
      );
    });

    eventBus.subscribe("task.statusChanged", (payload) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } =
        payload as TaskStatusChangedPayload;
      if (!assigneeId) return; // no one to notify
      this.createNotification(
        assigneeId,
        `Task "${taskTitle}" (${taskId}) status changed from "${oldStatus}" to "${newStatus}".`
      );
    });

    eventBus.subscribe("comment.added", (payload) => {
      const { taskTitle, authorName, assigneeId } =
        payload as CommentAddedPayload;
      if (!assigneeId) return; // task has no assignee, nothing to notify
      this.createNotification(
        assigneeId,
        `${authorName} commented on task "${taskTitle}".`
      );
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) throw new Error(`Notification not found: ${id}`);
    notification.read = true;
    this.store.set(id, notification);
    return notification;
  }
}

/**
 * API Router — single HTTP entry point.
 * Parses requests, delegates to the appropriate service method,
 * and serialises responses as JSON.
 *
 * Services expose plain TypeScript methods; no service contains
 * any HTTP-handling code.
 */

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";

import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";

// ---- Helpers ----------------------------------------------------------------

/** Read and JSON-parse the request body. */
function readBody(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk: Buffer) => (data += chunk.toString()));
    req.on("end", () => {
      if (!data) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(data) as Record<string, unknown>);
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

/** Send a JSON response. */
function send(
  res: ServerResponse,
  status: number,
  body: unknown
): void {
  const json = JSON.stringify(body, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(json),
  });
  res.end(json);
}

/** Send a standardised error response. */
function sendError(res: ServerResponse, status: number, message: string): void {
  send(res, status, { error: message });
}

// ---- Route matching helpers -------------------------------------------------

type RouteSegments = string[];

/**
 * Match a URL pathname against a pattern.
 * Pattern segments starting with ":" are wildcards; their values are
 * returned in the `params` object.
 *
 * Example: matchPath("/tasks/abc/status", "/tasks/:id/status")
 *          → { id: "abc" }  (truthy)
 *
 * Returns null when the path does not match.
 */
function matchPath(
  pathname: string,
  pattern: string
): Record<string, string> | null {
  const pathSegs: RouteSegments = pathname.split("/").filter(Boolean);
  const patternSegs: RouteSegments = pattern.split("/").filter(Boolean);

  if (pathSegs.length !== patternSegs.length) return null;

  const params: Record<string, string> = {};
  for (let i = 0; i < patternSegs.length; i++) {
    const pSeg = patternSegs[i];
    const uSeg = pathSegs[i];
    if (pSeg.startsWith(":")) {
      params[pSeg.slice(1)] = uSeg;
    } else if (pSeg !== uSeg) {
      return null;
    }
  }
  return params;
}

// ---- Router class -----------------------------------------------------------

export class Router {
  constructor(
    private userService: UserService,
    private projectService: ProjectService,
    private taskService: TaskService,
    private commentService: CommentService,
    private notificationService: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const baseUrl = `http://${req.headers.host ?? "localhost"}`;
    const url = new URL(req.url ?? "/", baseUrl);
    const pathname = url.pathname;
    const method = req.method ?? "GET";

    try {
      // ---- USER routes -------------------------------------------------------
      // GET /users
      if (method === "GET" && matchPath(pathname, "/users") !== null) {
        return send(res, 200, this.userService.getAll());
      }
      // POST /users
      if (method === "POST" && matchPath(pathname, "/users") !== null) {
        const body = await readBody(req);
        const user = this.userService.create(
          body.name as string,
          body.email as string
        );
        return send(res, 201, user);
      }
      // GET /users/:id
      {
        const params = matchPath(pathname, "/users/:id");
        if (params && method === "GET") {
          return send(res, 200, this.userService.getById(params.id));
        }
        // PUT /users/:id
        if (params && method === "PUT") {
          const body = await readBody(req);
          return send(res, 200, this.userService.update(params.id, body as { name?: string; email?: string }));
        }
        // DELETE /users/:id
        if (params && method === "DELETE") {
          this.userService.delete(params.id);
          return send(res, 204, null);
        }
      }

      // ---- PROJECT routes ----------------------------------------------------
      // GET /projects
      if (method === "GET" && matchPath(pathname, "/projects") !== null) {
        return send(res, 200, this.projectService.getAll());
      }
      // POST /projects
      if (method === "POST" && matchPath(pathname, "/projects") !== null) {
        const body = await readBody(req);
        const project = this.projectService.create(
          body.name as string,
          body.description as string
        );
        return send(res, 201, project);
      }
      // GET|PUT|DELETE /projects/:id
      {
        const params = matchPath(pathname, "/projects/:id");
        if (params) {
          if (method === "GET") {
            return send(res, 200, this.projectService.getById(params.id));
          }
          if (method === "PUT") {
            const body = await readBody(req);
            return send(res, 200, this.projectService.update(params.id, body as { name?: string; description?: string }));
          }
          if (method === "DELETE") {
            this.projectService.delete(params.id);
            return send(res, 204, null);
          }
        }
      }
      // POST /projects/:id/members
      {
        const params = matchPath(pathname, "/projects/:id/members");
        if (params) {
          if (method === "POST") {
            const body = await readBody(req);
            return send(res, 200, this.projectService.addMember(params.id, body.userId as string));
          }
          // DELETE /projects/:id/members
          if (method === "DELETE") {
            const body = await readBody(req);
            return send(res, 200, this.projectService.removeMember(params.id, body.userId as string));
          }
        }
      }

      // ---- TASK routes -------------------------------------------------------
      // GET /tasks?projectId=X
      if (method === "GET" && matchPath(pathname, "/tasks") !== null) {
        const projectId = url.searchParams.get("projectId");
        if (projectId) {
          return send(res, 200, this.taskService.getByProject(projectId));
        }
        return sendError(res, 400, "projectId query parameter is required");
      }
      // POST /tasks
      if (method === "POST" && matchPath(pathname, "/tasks") !== null) {
        const body = await readBody(req);
        const task = this.taskService.create(
          body.title as string,
          body.description as string,
          body.projectId as string
        );
        return send(res, 201, task);
      }
      // PUT /tasks/:id/status
      {
        const params = matchPath(pathname, "/tasks/:id/status");
        if (params && method === "PUT") {
          const body = await readBody(req);
          const task = this.taskService.changeStatus(
            params.id,
            body.status as "todo" | "in-progress" | "done"
          );
          return send(res, 200, task);
        }
      }
      // PUT /tasks/:id/assign
      {
        const params = matchPath(pathname, "/tasks/:id/assign");
        if (params && method === "PUT") {
          const body = await readBody(req);
          const task = this.taskService.assign(
            params.id,
            (body.assigneeId as string | null) ?? null
          );
          return send(res, 200, task);
        }
      }
      // GET|PUT|DELETE /tasks/:id
      {
        const params = matchPath(pathname, "/tasks/:id");
        if (params) {
          if (method === "GET") {
            return send(res, 200, this.taskService.getById(params.id));
          }
          if (method === "PUT") {
            const body = await readBody(req);
            return send(res, 200, this.taskService.update(params.id, body as { title?: string; description?: string }));
          }
          if (method === "DELETE") {
            this.taskService.delete(params.id);
            return send(res, 204, null);
          }
        }
      }

      // ---- COMMENT routes ----------------------------------------------------
      // GET /comments?taskId=X
      if (method === "GET" && matchPath(pathname, "/comments") !== null) {
        const taskId = url.searchParams.get("taskId");
        if (taskId) {
          return send(res, 200, this.commentService.getByTask(taskId));
        }
        return sendError(res, 400, "taskId query parameter is required");
      }
      // POST /comments
      if (method === "POST" && matchPath(pathname, "/comments") !== null) {
        const body = await readBody(req);
        const taskId = body.taskId as string;
        const authorId = body.authorId as string;
        const commentBody = body.body as string;

        // Resolve display names in the router so comment-service stays decoupled
        const task = this.taskService.getById(taskId);
        const author = this.userService.getById(authorId);

        // Pass assigneeId via the event payload so notification-service can
        // notify the task assignee without querying task-service directly.
        // We embed it in the event payload inside comment-service by passing
        // it as an extra field through the body here.
        // Because comment-service's create() already publishes the event,
        // we need to attach assigneeId BEFORE the publish. We do this by
        // temporarily monkey-patching — actually, cleanest approach is to
        // just pass it as a parameter to create() and let it forward it.
        // We'll add assigneeId as an extra param (see comment-service).
        const comment = this.commentService.create(
          taskId,
          authorId,
          commentBody,
          task.title,
          author.name,
          task.assigneeId  // forwarded so NotificationService can notify assignee
        );
        return send(res, 201, comment);
      }
      // GET|DELETE /comments/:id
      {
        const params = matchPath(pathname, "/comments/:id");
        if (params) {
          if (method === "GET") {
            return send(res, 200, this.commentService.getById(params.id));
          }
          if (method === "DELETE") {
            this.commentService.delete(params.id);
            return send(res, 204, null);
          }
        }
      }

      // ---- NOTIFICATION routes -----------------------------------------------
      // GET /notifications?userId=X
      if (method === "GET" && matchPath(pathname, "/notifications") !== null) {
        const userId = url.searchParams.get("userId");
        if (userId) {
          return send(res, 200, this.notificationService.getByUser(userId));
        }
        return sendError(res, 400, "userId query parameter is required");
      }
      // PUT /notifications/:id/read
      {
        const params = matchPath(pathname, "/notifications/:id/read");
        if (params && method === "PUT") {
          return send(res, 200, this.notificationService.markAsRead(params.id));
        }
      }

      // ---- 404 ---------------------------------------------------------------
      sendError(res, 404, `Cannot ${method} ${pathname}`);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Distinguish "not found" errors from general server errors
      if (message.includes("not found") || message.toLowerCase().includes("not found")) {
        sendError(res, 404, message);
      } else if (
        message.includes("Invalid status transition") ||
        message.includes("required") ||
        message.includes("Invalid JSON")
      ) {
        sendError(res, 400, message);
      } else {
        sendError(res, 500, message);
      }
    }
  }
}

/**
 * Comment Service — manages comments on tasks.
 * Owns its own in-memory data store (Map<string, Comment>).
 *
 * Events published:
 *   comment.added  { commentId, taskId, taskTitle, authorId, authorName, assigneeId }
 *
 * `taskTitle`, `authorName`, and `assigneeId` are supplied by the router at
 * call time so this service never imports or calls other services directly
 * (enforces ADR-001 / ADR-002).  The `assigneeId` is forwarded in the event
 * payload so that NotificationService can notify the task assignee without
 * ever reaching into TaskService's store.
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus.js";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();

  constructor(private eventBus: EventBus) {}

  /**
   * Create a comment and publish a `comment.added` event.
   *
   * @param taskId     - ID of the task being commented on
   * @param authorId   - ID of the user writing the comment
   * @param body       - Comment text
   * @param taskTitle  - Title of the task (resolved by the router)
   * @param authorName - Display name of the author (resolved by the router)
   * @param assigneeId - Current assignee of the task, if any (resolved by the router)
   */
  create(
    taskId: string,
    authorId: string,
    body: string,
    taskTitle: string,
    authorName: string,
    assigneeId: string | null = null
  ): Comment {
    if (!taskId || !authorId || !body) {
      throw new Error("taskId, authorId, and body are required");
    }
    const comment: Comment = {
      id: randomUUID(),
      taskId,
      authorId,
      body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    this.eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId,
      taskTitle,
      authorId,
      authorName,
      assigneeId, // forwarded to NotificationService via the event payload
    });

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

