server.listen(DEMO_PORT, () => {
  console.log(`\n[Demo] Server started on port ${DEMO_PORT}`);
  runDemo().finally(() => {
    server.close(() => {
      console.log("[Demo] Server closed.");
      process.exit(process.exitCode ?? 0);
    });
  });
});

